library IEEE;
use IEEE.STD_LOGIC_1164.ALL;
library UNISIM;
use UNISIM.VCOMPONENTS.ALL;
entity fifo_generator_ramfifo is
  port (
    empty : out STD_LOGIC;
    full : out STD_LOGIC;
    overflow : out STD_LOGIC;
    rd_clk : in STD_LOGIC;
    rd_en : in STD_LOGIC;
    rst : in STD_LOGIC;
    underflow : out STD_LOGIC;
    wr_clk : in STD_LOGIC;
    wr_en : in STD_LOGIC;
    din : in STD_LOGIC_VECTOR ( 15 downto 0 );
    dout : out STD_LOGIC_VECTOR ( 15 downto 0 )
  );
end fifo_generator_ramfifo;

architecture STRUCTURE of fifo_generator_ramfifo is
  signal \gntv_or_sync_fifo.gcx.clkx_n_0\ : STD_LOGIC;
  signal \gntv_or_sync_fifo.gl0.rd_n_7\ : STD_LOGIC;
  signal \gntv_or_sync_fifo.gl0.rd_n_8\ : STD_LOGIC;
  signal \gntv_or_sync_fifo.gl0.rd_n_9\ : STD_LOGIC;
  signal \gntv_or_sync_fifo.gl0.wr_n_1\ : STD_LOGIC;
  signal ram_rd_en_i : STD_LOGIC;
  signal ram_wr_en : STD_LOGIC;
  signal rd_pntr : STD_LOGIC_VECTOR ( 3 downto 0 );
  signal rd_rst_i : STD_LOGIC_VECTOR ( 2 downto 1 );
  signal rst_full_ff_i : STD_LOGIC;
  signal wr_pntr : STD_LOGIC_VECTOR ( 3 downto 0 );
  signal wr_pntr_plus1 : STD_LOGIC_VECTOR ( 3 downto 0 );
  signal wr_pntr_plus2 : STD_LOGIC_VECTOR ( 3 downto 0 );
  signal wr_pntr_rd : STD_LOGIC_VECTOR ( 3 downto 0 );
  signal wr_rst_i : STD_LOGIC_VECTOR ( 1 to 1 );
begin
\gntv_or_sync_fifo.gcx.clkx\: entity work.clk_x_pntrs
     port map (
      AR(0) => rst_full_ff_i,
      D(2) => \gntv_or_sync_fifo.gl0.rd_n_7\,
      D(1) => \gntv_or_sync_fifo.gl0.rd_n_8\,
      D(0) => \gntv_or_sync_fifo.gl0.rd_n_9\,
      Q(3 downto 0) => wr_pntr_plus1(3 downto 0),
      \Q_reg_reg[0]\(0) => rd_rst_i(1),
      \gnxpm_cdc.rd_pntr_gc_reg[3]_0\(0) => rd_pntr(3),
      \gnxpm_cdc.wr_pntr_bin_reg[3]_0\(3 downto 0) => wr_pntr_rd(3 downto 0),
      \gnxpm_cdc.wr_pntr_gc_reg[3]_0\(3 downto 0) => wr_pntr(3 downto 0),
      \out\ => \gntv_or_sync_fifo.gl0.wr_n_1\,
      ram_full_fb_i_reg => \gntv_or_sync_fifo.gcx.clkx_n_0\,
      ram_full_fb_i_reg_0(3 downto 0) => wr_pntr_plus2(3 downto 0),
      rd_clk => rd_clk,
      wr_clk => wr_clk,
      wr_en => wr_en
    );
\gntv_or_sync_fifo.gl0.rd\: entity work.rd_logic
     port map (
      AR(0) => rd_rst_i(2),
      D(2) => \gntv_or_sync_fifo.gl0.rd_n_7\,
      D(1) => \gntv_or_sync_fifo.gl0.rd_n_8\,
      D(0) => \gntv_or_sync_fifo.gl0.rd_n_9\,
      E(0) => ram_rd_en_i,
      Q(3 downto 0) => rd_pntr(3 downto 0),
      empty => empty,
      ram_empty_i_reg(3 downto 0) => wr_pntr_rd(3 downto 0),
      rd_clk => rd_clk,
      rd_en => rd_en,
      underflow => underflow
    );
\gntv_or_sync_fifo.gl0.wr\: entity work.wr_logic
     port map (
      E(0) => ram_wr_en,
      Q(3 downto 0) => wr_pntr_plus2(3 downto 0),
      full => full,
      \gic0.gc0.count_d1_reg[3]\(3 downto 0) => wr_pntr_plus1(3 downto 0),
      \gic0.gc0.count_d2_reg[3]\(3 downto 0) => wr_pntr(3 downto 0),
      \gic0.gc0.count_reg[0]\(1) => wr_rst_i(1),
      \gic0.gc0.count_reg[0]\(0) => rst_full_ff_i,
      \out\ => \gntv_or_sync_fifo.gl0.wr_n_1\,
      overflow => overflow,
      ram_full_fb_i_reg => \gntv_or_sync_fifo.gcx.clkx_n_0\,
      wr_clk => wr_clk,
      wr_en => wr_en
    );
\gntv_or_sync_fifo.mem\: entity work.memory
     port map (
      E(0) => ram_rd_en_i,
      EN => ram_wr_en,
      Q(3 downto 0) => rd_pntr(3 downto 0),
      din(15 downto 0) => din(15 downto 0),
      dout(15 downto 0) => dout(15 downto 0),
      \gpr1.dout_i_reg[1]\(3 downto 0) => wr_pntr(3 downto 0),
      rd_clk => rd_clk,
      wr_clk => wr_clk
    );
rstblk: entity work.reset_blk_ramfifo
     port map (
      \ngwrdrst.grst.g7serrst.rd_rst_reg_reg[2]_0\(1 downto 0) => rd_rst_i(2 downto 1),
      \out\(1) => wr_rst_i(1),
      \out\(0) => rst_full_ff_i,
      rd_clk => rd_clk,
      rst => rst,
      wr_clk => wr_clk
    );
end STRUCTURE;
